        foreach ($products as &$product) {
            $product['created_at'] = $now;
            $product['updated_at'] = $now;
        }
        unset($product);

        // Process in batches so 3,716 products do not become one huge query.
        foreach (array_chunk($products, 500) as $chunk) {
            DB::table('products')->upsert(
                $chunk,
                ['article_code'],
                ['name', 'size', 'type', 'series', 'brand', 'updated_at']
            );
        }

        $this->command->info(
